package dev.packsmith.mt; import bin.mt.plugin.api.editor.TextEditor; import bin.mt.plugin.api.ui.PluginUI; public class GenerateLinkedBehaviorPackMenu extends CompatMenuBase { public String name(){return "Generate linked BP manifest";} public void onMenuClick(PluginUI ui,TextEditor e){CharSequence clip=ctx().getClipboardText();String u=clip==null?null:clip.toString();if(u==null||!u.matches("[0-9a-fA-F-]{36}")){ui.showToast("Copy an RP header UUID first");return;}EditorUtil.replaceWhole(e,ManifestUtil.linkedBp(ctx(),u));ui.showToast("Linked BP generated from clipboard RP UUID");}}